import { NextRequest, NextResponse } from 'next/server'
import { scrypt as scryptCb, timingSafeEqual } from 'crypto'
import { promisify } from 'util'
import { setTimeout as sleep } from 'timers/promises'
import { SESSION_TTL_SECONDS, sessionCookie, signSession } from '@/lib/partner-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

/**
 * Partner-area login. Credentials come from `PARTNER_LOGINS`
 * (`name:<salt-hex>:<scrypt-hex>,…`, generated by `scripts/partner-hash.js`); sessions are signed
 * cookies (`lib/partner-session.ts`). Five failures lock the login name for 24 h and the IP for
 * 15 min; both counters live in process memory, which is enough for a demo deployment and
 * resets when the instance recycles. Every failure costs a 2 s delay and the same generic error.
 */
const MAX_FAILURES = 5
const IP_LOCK_MS = 15 * 60 * 1000
const USER_LOCK_MS = 24 * 60 * 60 * 1000
const FAIL_DELAY_MS = 2000
const SCRYPT = { N: 16384, r: 8, p: 1, keylen: 32 }

interface Counter {
  failures: number
  lockedUntil: number
  firstFailure: number
}
const counters = new Map<string, Counter>()

function counter(key: string, now: number): Counter {
  let c = counters.get(key)
  if (!c || (c.lockedUntil && c.lockedUntil <= now) || (c.firstFailure && now - c.firstFailure > IP_LOCK_MS && !c.lockedUntil)) {
    c = { failures: 0, lockedUntil: 0, firstFailure: 0 }
    counters.set(key, c)
  }
  return c
}

function fail(key: string, now: number, lockMs: number) {
  const c = counter(key, now)
  c.failures += 1
  if (!c.firstFailure) c.firstFailure = now
  if (c.failures >= MAX_FAILURES) c.lockedUntil = now + lockMs
}

function parseLogins(): Map<string, { salt: Buffer; hash: Buffer }> {
  const out = new Map<string, { salt: Buffer; hash: Buffer }>()
  for (const entry of (process.env.PARTNER_LOGINS || '').split(',')) {
    const [name, salt, hash] = entry.trim().split(':')
    if (name && salt && hash) out.set(name, { salt: Buffer.from(salt, 'hex'), hash: Buffer.from(hash, 'hex') })
  }
  return out
}

const scrypt = promisify(scryptCb) as (password: string, salt: Buffer, keylen: number, opts: { N: number; r: number; p: number }) => Promise<Buffer>

const derive = (password: string, salt: Buffer) => scrypt(password, salt, SCRYPT.keylen, { N: SCRYPT.N, r: SCRYPT.r, p: SCRYPT.p })

function loginUrl(request: NextRequest, error: string, next: string): URL {
  const url = new URL('/partnerapi/login', request.nextUrl.origin)
  url.searchParams.set('error', error)
  if (next) url.searchParams.set('next', next)
  return url
}

function safeNext(value: string): string {
  return /^\/partnerapi(\/[A-Za-z0-9/_-]*)?$/.test(value) && value !== '/partnerapi/login' ? value : '/partnerapi'
}

function sameOrigin(request: NextRequest): boolean {
  const source = request.headers.get('origin') || request.headers.get('referer')
  if (!source) return false
  try {
    return new URL(source).host === request.headers.get('host')
  } catch {
    return false
  }
}

export async function POST(request: NextRequest) {
  const now = Date.now()
  const ip = request.headers.get('x-forwarded-for')?.split(',')[0].trim() || request.ip || 'unknown'
  const form = await request.formData().catch(() => null)
  const name = String(form?.get('partner') || '').trim().toLowerCase()
  const password = String(form?.get('password') || '')
  const next = safeNext(String(form?.get('next') || ''))

  if (!sameOrigin(request)) return NextResponse.redirect(loginUrl(request, 'origin', next), 303)

  const secret = process.env.PARTNER_SESSION_SECRET
  const logins = parseLogins()
  if (!secret || logins.size === 0) {
    console.error('partner login: PARTNER_SESSION_SECRET / PARTNER_LOGINS not configured')
    return NextResponse.redirect(loginUrl(request, 'unavailable', next), 303)
  }

  const ipCounter = counter(`ip:${ip}`, now)
  const userCounter = counter(`user:${name}`, now)
  if (ipCounter.lockedUntil > now || userCounter.lockedUntil > now) {
    console.log('partner login locked', { partner: name, status: 429 })
    return NextResponse.redirect(loginUrl(request, 'locked', next), 303)
  }

  const record = logins.get(name)
  // Always run scrypt so unknown names cost the same time as wrong passwords.
  const derived = await derive(password, record?.salt ?? Buffer.alloc(16))
  const ok = !!record && derived.length === record.hash.length && timingSafeEqual(derived, record.hash) && password.length > 0

  if (!ok) {
    fail(`ip:${ip}`, now, IP_LOCK_MS)
    if (name) fail(`user:${name}`, now, USER_LOCK_MS)
    console.log('partner login failed', { partner: name || '-', status: 401 })
    await sleep(FAIL_DELAY_MS)
    const locked = counter(`ip:${ip}`, now).lockedUntil > now || (name && counter(`user:${name}`, now).lockedUntil > now)
    return NextResponse.redirect(loginUrl(request, locked ? 'locked' : 'invalid', next), 303)
  }

  counters.delete(`user:${name}`)
  const token = await signSession(secret, name, now)
  console.log('partner login ok', { partner: name, status: 303 })
  const res = NextResponse.redirect(new URL(next, request.nextUrl.origin), 303)
  res.headers.append('Set-Cookie', sessionCookie(token, SESSION_TTL_SECONDS))
  res.headers.set('Cache-Control', 'no-store')
  return res
}
